import React, { useMemo, useState } from 'react';
import LogFilterBar from '../../components/logs/LogFilterBar';
import LogTable from '../../components/logs/LogTable';
import LogDetailModal from '../../components/logs/LogDetailModal';
import { useLogs } from '../../hooks/UseLogs';
import { exportLogs, deleteLog, deleteLogs } from '../../api/LogsApi';

function safeNum(v, fallback = 0) {
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
}

function parseDateSafe(v) {
  if (!v) return null;
  const d = new Date(v);
  return Number.isFinite(d.getTime()) ? d : null;
}

function downloadAsFile(filename, content, mimeType = 'application/octet-stream') {
  const blob =
    content instanceof Blob
      ? content
      : new Blob([typeof content === 'string' ? content : JSON.stringify(content, null, 2)], {
          type: mimeType,
        });

  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

function makeStamp() {
  const now = new Date();
  return `${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, '0')}${String(now.getDate()).padStart(
    2,
    '0'
  )}_${String(now.getHours()).padStart(2, '0')}${String(now.getMinutes()).padStart(2, '0')}`;
}

function LogsPage() {
  const {
    logs,
    loading,
    error,

    page,
    setPage,
    size,
    setSize,
    total,

    filters,
    setFilters,

    refresh,
    search,
  } = useLogs(50);

  const [selectedLogId, setSelectedLogId] = useState(null);

  const visibleLogs = useMemo(() => {
    const keyword = (filters.keyword || '').trim().toLowerCase();
    const aiLabel = filters.aiLabel;
    const from = filters.from;
    const to = filters.to;
    const sort = filters.sort || 'collectedAt,desc';

    const fromDate = from ? new Date(`${from}T00:00:00`) : null;
    const toDate = to ? new Date(`${to}T23:59:59`) : null;

    const filtered = (logs || []).filter((log) => {
      const matchKeyword =
        !keyword ||
        String(log.path || '').toLowerCase().includes(keyword) ||
        String(log.eventType || '').toLowerCase().includes(keyword) ||
        String(log.aiDetail || '').toLowerCase().includes(keyword);

      const matchLabel = !aiLabel || log.aiLabel === aiLabel;

      let matchDate = true;
      if (fromDate || toDate) {
        const t = parseDateSafe(log.collectedAt);
        if (!t) matchDate = false;
        else {
          if (fromDate && t < fromDate) matchDate = false;
          if (toDate && t > toDate) matchDate = false;
        }
      }

      return matchKeyword && matchLabel && matchDate;
    });

    const [field, dirRaw] = String(sort).split(',');
    const dir = (dirRaw || 'desc').toLowerCase() === 'asc' ? 1 : -1;

    const sorted = [...filtered].sort((a, b) => {
      if (field === 'aiScore') return (safeNum(a.aiScore) - safeNum(b.aiScore)) * dir;
      if (field === 'entropy') return (safeNum(a.entropy) - safeNum(b.entropy)) * dir;

      const ta = parseDateSafe(a.collectedAt)?.getTime() ?? 0;
      const tb = parseDateSafe(b.collectedAt)?.getTime() ?? 0;
      return (ta - tb) * dir;
    });

    return sorted;
  }, [logs, filters.keyword, filters.aiLabel, filters.from, filters.to, filters.sort]);

  const handleSelectLog = (log) => setSelectedLogId(log?.id || null);
  const handleCloseModal = () => setSelectedLogId(null);

  const runExport = async ({ format, ids, filtersPayload }) => {
    const res = await exportLogs({
      format,
      ids: ids || [],
      filters: filtersPayload || {},
    });

    if (res && typeof res === 'object' && res.downloadUrl) {
      window.open(res.downloadUrl, '_blank', 'noopener,noreferrer');
      return;
    }

    const stamp = makeStamp();
    if (format === 'CSV') {
      downloadAsFile(`logs_export_${stamp}.csv`, typeof res === 'string' ? res : JSON.stringify(res), 'text/csv');
    } else {
      downloadAsFile(`logs_export_${stamp}.json`, res, 'application/json');
    }
  };

  const handleExportSelected = async (format, ids) => {
    if (!ids || ids.length === 0) return;

    try {
      await runExport({
        format,
        ids,
        filtersPayload: { page, size, ...filters },
      });
    } catch (e) {
      alert('선택 내보내기 실패: ' + e.message);
    }
  };

  const handleExportAll = async (format) => {
    const ok = window.confirm(
      '현재 필터 조건 전체를 내보낼까요?\n(데이터가 많으면 시간이 걸릴 수 있어요)'
    );
    if (!ok) return;

    try {
      await runExport({
        format,
        ids: [],
        filtersPayload: { page, size, ...filters },
      });
    } catch (e) {
      alert('전체 내보내기 실패: ' + e.message);
    }
  };

  const handleDeleteSelected = async (ids) => {
    if (!ids || ids.length === 0) return;

    const ok = window.confirm(`선택한 로그 ${ids.length}개를 삭제할까요?`);
    if (!ok) return;

    try {
      await deleteLogs(ids);
      await refresh();
      if (selectedLogId && ids.includes(selectedLogId)) setSelectedLogId(null);
    } catch (e) {
      alert('선택 삭제 실패: ' + e.message);
    }
  };

  // ✅ 이걸 모달에서도 그대로 재사용(onDelete로 전달)
  const handleDeleteOne = async (id) => {
    const ok = window.confirm(`로그(ID: ${id})를 삭제할까요?`);
    if (!ok) return;

    try {
      await deleteLog(id);
      await refresh();
      if (selectedLogId === id) setSelectedLogId(null);
    } catch (e) {
      alert('삭제 실패: ' + e.message);
      throw e; // 모달에서 deleteError 표시 가능
    }
  };

  return (
    <div className="page-container">
      <h1>로그 관리</h1>

      <LogFilterBar
        keyword={filters.keyword}
        setKeyword={(val) => setFilters((p) => ({ ...p, keyword: val }))}

        riskFilter={filters.aiLabel || 'ALL'}
        setRiskFilter={(v) => setFilters((p) => ({ ...p, aiLabel: v === 'ALL' ? '' : v }))}

        from={filters.from}
        setFrom={(val) => setFilters((p) => ({ ...p, from: val }))}

        to={filters.to}
        setTo={(val) => setFilters((p) => ({ ...p, to: val }))}

        sort={filters.sort}
        setSort={(val) => setFilters((p) => ({ ...p, sort: val }))}

        onSearch={() => {
          setPage(1);
          search();
        }}
        onRefresh={refresh}
      />

      <div style={{ display: 'flex', gap: 8, alignItems: 'center', margin: '12px 0' }}>
        <select value={size} onChange={(e) => setSize(Number(e.target.value) || 50)}>
          <option value={20}>20</option>
          <option value={50}>50</option>
          <option value={100}>100</option>
        </select>

        <button className="btn" onClick={() => setPage((p) => Math.max(1, p - 1))}>
          이전
        </button>
        <span>page: {page}</span>
        <button className="btn" onClick={() => setPage((p) => p + 1)}>
          다음
        </button>

        {total != null && (
          <span style={{ marginLeft: 8, color: '#9ca3af' }}>
            total: {total}
          </span>
        )}
      </div>

      {loading && <p>불러오는 중...</p>}
      {error && <p style={{ color: 'red' }}>오류: {error.message}</p>}

      {!loading && !error && (
        <LogTable
          logs={visibleLogs}
          onSelectLog={handleSelectLog}
          onExport={handleExportSelected}
          onExportAll={handleExportAll}
          onDeleteSelected={handleDeleteSelected}
          onDeleteOne={handleDeleteOne}
        />
      )}

      {selectedLogId && (
        <LogDetailModal
          logId={selectedLogId}
          onClose={handleCloseModal}
          onDelete={handleDeleteOne}   // ✅ 모달 안 삭제 버튼 연결
        />
      )}
    </div>
  );
}

export default LogsPage;
